'use client';

import { useEffect, useRef } from 'react';

// Rodin's Thinker drawn in text (filled with "BUILD"), looking at a 3D laptop whose
// screen lights the front of his body. The art is precomputed on a character grid
// (src/data/thinker-ascii.ts, generated by src/design/thinker/export_thinker.py);
// this component only lays it out and animates it:
//   - a top-down scan-in when the hero is revealed,
//   - the BUILD letters drifting slowly through the figure,
//   - the screen's light filling the air between the laptop and the front of his
//     body as one continuous, wide glow (a fan, not a beam), densest at the screen;
//     the screen, that glow and his pale tint breathe together, and the lit dust
//     in the air twinkles slowly.
// Canvas 2D with a glyph atlas. Pauses off-screen; static under reduced motion.

const FRAME_MS = 70;          // ~14 fps: plenty for a slow breath and twinkle
const FLOW_MS = 900;          // one letter step: slow enough for peripheral vision
const BREATH_MS = 5200;       // one slow breath of the screen's brightness
const TWINKLE_MS = 2600;      // how slowly the lit dust in the air shimmers
const LIGHT_FAN = (62 * Math.PI) / 180;  // half-angle of the light: a wide glow, not a beam
const REVEAL_MS = 1400;
// How far the faint halo left of the laptop may spill out of the box, toward the
// copy. The box starts ~36px past the copy, so this stops short of the text.
const HALO_SPILL_PX = 28;

interface Art {
    cols: number;
    rows: number;
    cell: { w: number; h: number };
    floorRow: number;
    inkCol: number;
    screen: { col: number; row: number };
    word: string;
    colours: readonly string[];
    glyphs: readonly string[];
    colourRows: readonly string[];
    alphaRows: readonly string[];
    backingRows: readonly string[];
}

interface AsciiThinkerProps {
    revealed?: boolean;
    className?: string;
    style?: React.CSSProperties;
}

export function AsciiThinker({ revealed = true, className = '', style }: AsciiThinkerProps) {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const revealedRef = useRef(revealed);
    const startRevealRef = useRef<(() => void) | null>(null);

    useEffect(() => {
        revealedRef.current = revealed;
        if (revealed) startRevealRef.current?.();
    }, [revealed]);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        let disposed = false;
        let art: Art | null = null;

        // Flattened cells
        let n = 0;
        let cCol = new Int16Array(0), cRow = new Int16Array(0);
        let cGlyph = new Int16Array(0);      // index into glyph set (static glyph)
        let cLetter = new Int8Array(0);      // -1, or position of the letter in the word
        let cUpper = new Uint8Array(0);
        let cColour = new Uint8Array(0);
        let cAlpha = new Float32Array(0);
        let glyphSet: string[] = [];
        let upperIdx: number[] = [], lowerIdx: number[] = [];
        // Empty cells in the fan between the screen and his body: the screen's light
        let wn = 0;
        let wCol = new Int16Array(0), wRow = new Int16Array(0);
        let wPos = new Float32Array(0);      // 0 at the screen .. 1 at his body
        let wFan = new Float32Array(0);      // 1 on the axis, fading to the fan's edges
        let wNoise = new Float32Array(0);    // per-cell threshold: sparse, stable dots
        let gDot = 0, gMid = 0, gColon = 0;

        let width = 0, height = 0, dpr = 1, cw = 0, chh = 0, gx = 0, gy = 0;
        let atlas: HTMLCanvasElement | null = null;
        // Per row, the cells of the silhouette (shadows included) painted black under
        // the glyphs, so the hero's dot grid doesn't show through the figure.
        let backing: Path2D[] = [];

        let raf: number | null = null;
        let last = 0;
        let reveal = reduced ? 1 : 0;
        let revealStart = -1;
        let t0 = performance.now();

        const prepare = (a: Art) => {
            const set = new Set<string>();
            for (const ch of a.word.toUpperCase() + a.word.toLowerCase() + '.·:') set.add(ch);
            const cells: [number, number, string, number, number][] = [];
            for (let r = 0; r < a.rows; r++) {
                const g = a.glyphs[r], c0 = a.colourRows[r], a0 = a.alphaRows[r];
                for (let c = 0; c < a.cols; c++) {
                    const ch = g[c];
                    if (!ch || ch === ' ') continue;
                    set.add(ch);
                    cells.push([c, r, ch, Number(c0[c]), (Number(a0[c]) + 1) / 10]);
                }
            }
            glyphSet = [...set];
            const index = new Map(glyphSet.map((ch, i) => [ch, i]));
            upperIdx = [...a.word.toUpperCase()].map((ch) => index.get(ch)!);
            lowerIdx = [...a.word.toLowerCase()].map((ch) => index.get(ch)!);
            n = cells.length;
            cCol = new Int16Array(n); cRow = new Int16Array(n); cGlyph = new Int16Array(n);
            cLetter = new Int8Array(n); cUpper = new Uint8Array(n); cColour = new Uint8Array(n);
            cAlpha = new Float32Array(n);
            const upper = a.word.toUpperCase(), lower = a.word.toLowerCase();
            cells.forEach(([c, r, ch, col, al], i) => {
                cCol[i] = c; cRow[i] = r; cGlyph[i] = index.get(ch)!;
                cColour[i] = col; cAlpha[i] = al;
                const u = upper.indexOf(ch), l = lower.indexOf(ch);
                cLetter[i] = u >= 0 ? u : l;
                cUpper[i] = u >= 0 ? 1 : 0;
            });
            gDot = index.get('.')!; gMid = index.get('·')!; gColon = index.get(':')!;

            // The light: aimed from the screen at the middle of the screen-lit cells (the
            // front of his body), reaching as far as the farthest of them.
            const sx = a.screen.col, sy = a.screen.row, aspect = a.cell.h / a.cell.w;
            let tx = 0, ty = 0, tn = 0, reach = 0;
            cells.forEach(([c, r, , col]) => {
                if (col !== 1 && col !== 2) return;
                tx += c; ty += r; tn++;
                reach = Math.max(reach, Math.hypot(c - sx, (r - sy) * aspect));
            });
            if (!tn) { wn = 0; return; }
            tx /= tn; ty /= tn;
            const ax = tx - sx, ay = (ty - sy) * aspect, al = Math.hypot(ax, ay);
            const wc: number[] = [], wr: number[] = [], wp: number[] = [], wf: number[] = [], wz: number[] = [];
            for (let r = 0; r < a.rows; r++) {
                for (let c = 0; c < a.cols; c++) {
                    const ch = a.glyphs[r][c];
                    if ((ch && ch !== ' ') || a.backingRows[r][c] === '1') continue;   // air only
                    const dx = c - sx, dy = (r - sy) * aspect, d = Math.hypot(dx, dy);
                    if (d < 3 || d > reach) continue;
                    const ang = Math.acos(Math.max(-1, Math.min(1, (dx * ax + dy * ay) / (d * al))));
                    if (ang > LIGHT_FAN) continue;
                    let h = (c * 374761393 + r * 668265263) | 0;
                    h = Math.imul(h ^ (h >>> 13), 1274126177);
                    wc.push(c); wr.push(r); wp.push(d / reach);
                    wf.push(Math.cos((ang / LIGHT_FAN) * (Math.PI / 2)));
                    wz.push(((h ^ (h >>> 16)) >>> 0) / 4294967296);
                }
            }
            wn = wc.length;
            wCol = Int16Array.from(wc); wRow = Int16Array.from(wr);
            wPos = Float32Array.from(wp); wFan = Float32Array.from(wf); wNoise = Float32Array.from(wz);
        };

        const buildAtlas = () => {
            if (!art) return;
            const a = document.createElement('canvas');
            a.width = Math.ceil(glyphSet.length * cw * dpr);
            a.height = Math.ceil(art.colours.length * chh * dpr);
            const g = a.getContext('2d')!;
            g.scale(dpr, dpr);
            g.font = `bold ${chh}px ui-monospace, SFMono-Regular, Menlo, monospace`;
            g.textBaseline = 'top';
            art.colours.forEach((colour, ci) => {
                g.fillStyle = colour;
                glyphSet.forEach((ch, gi) => g.fillText(ch, gi * cw, ci * chh));
            });
            atlas = a;
        };

        const layout = () => {
            if (!art) return;
            const box = (canvas.parentElement ?? canvas).getBoundingClientRect();
            // The box's bottom edge is the floor (the hero's SYS.ACT rule): the art's
            // floor row stands on it, right-aligned. What has to fit is the figure and
            // the laptop (from the first ink column); the faint halo left of the laptop
            // may spill a little past the box's left edge instead of costing scale.
            const standing = art.floorRow + 1;
            const inkCols = art.cols - art.inkCol;
            const scale = Math.min(box.width / (inkCols * art.cell.w), box.height / (standing * art.cell.h));
            cw = art.cell.w * scale;
            chh = art.cell.h * scale;
            const spill = Math.min(HALO_SPILL_PX, Math.max(0, art.cols * cw - box.width));
            width = box.width + spill;
            height = box.height;
            canvas.style.left = `${-spill}px`;
            canvas.style.width = `${width}px`;
            canvas.style.height = `${height}px`;
            dpr = Math.min(window.devicePixelRatio || 1, 2);
            canvas.width = Math.round(width * dpr);
            canvas.height = Math.round(height * dpr);
            gx = width - art.cols * cw;
            gy = height - standing * chh;
            backing = art.backingRows.map((row) => {
                const path = new Path2D();
                let c = 0;
                while (c < row.length) {
                    if (row[c] !== '1') { c++; continue; }
                    let end = c;
                    while (end < row.length && row[end] === '1') end++;
                    path.rect(gx + c * cw - 0.5, 0, (end - c) * cw + 1, chh + 1);
                    c = end;
                }
                return path;
            });
            buildAtlas();
        };

        const draw = (now: number) => {
            if (!art || !atlas) return;
            ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
            ctx.clearRect(0, 0, width, height);
            const t = now - t0;
            const shift = reduced ? 0 : Math.floor(t / FLOW_MS);
            // One slow breath drives the screen, the light in the air and his tint
            // together, so they read as one light source.
            const breath = reduced ? 1 : 0.86 + 0.14 * (0.5 + 0.5 * Math.sin((t / BREATH_MS) * Math.PI * 2));
            const lit = reveal >= 1;
            const revealRow = reveal * (art.rows + 6);
            const wl = art.word.length;
            const sw = cw * dpr, sh = chh * dpr;
            ctx.fillStyle = '#000';
            for (let r = 0; r < art.rows && r <= revealRow; r++) {
                ctx.setTransform(dpr, 0, 0, dpr, 0, dpr * (gy + r * chh - 0.5));
                ctx.fill(backing[r]);
            }
            ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
            for (let i = 0; i < n; i++) {
                const r = cRow[i];
                if (r > revealRow) continue;
                let g = cGlyph[i];
                const k = cLetter[i];
                if (k >= 0) {
                    const j = (k + shift) % wl;
                    g = cUpper[i] ? upperIdx[j] : lowerIdx[j];
                }
                const col = cColour[i];
                let alpha = cAlpha[i];
                if (col >= 1 && col <= 4) alpha *= breath;   // screen light
                if (reveal < 1) {
                    const scan = Math.max(0, 1 - (revealRow - r) / 6);
                    alpha = Math.min(1, alpha + scan * 0.5);
                }
                ctx.globalAlpha = alpha;
                ctx.drawImage(atlas, g * sw, col * sh, sw, sh, gx + cCol[i] * cw, gy + r * chh, cw, chh);
            }
            if (lit) {
                // Continuous glow: strongest at the screen and on the fan's axis, thinning
                // out toward him. Each dot's threshold drifts slowly (twinkle) so the air
                // shimmers without any front moving through it.
                const tw = reduced ? 0 : t / TWINKLE_MS;
                for (let i = 0; i < wn; i++) {
                    const pos = wPos[i];
                    const inten = wFan[i] * (1 - 0.7 * pos) ** 1.3 * breath;
                    const z = wNoise[i];
                    const jitter = reduced ? 0 : 0.18 * Math.sin(tw * (0.6 + z) * Math.PI * 2 + z * 40);
                    if (inten < 0.22 + 0.62 * z + jitter) continue;
                    const g = inten > 0.66 ? gColon : inten > 0.4 ? gMid : gDot;
                    const col = inten > 0.55 ? 3 : 4;
                    ctx.globalAlpha = 0.12 + 0.42 * inten;
                    ctx.drawImage(atlas, g * sw, col * sh, sw, sh, gx + wCol[i] * cw, gy + wRow[i] * chh, cw, chh);
                }
            }
            ctx.globalAlpha = 1;
        };

        const tick = (now: number) => {
            raf = requestAnimationFrame(tick);
            if (now - last < FRAME_MS) return;
            last = now;
            if (revealStart >= 0 && reveal < 1) reveal = Math.min(1, (now - revealStart) / REVEAL_MS);
            draw(now);
        };

        const start = () => {
            if (raf !== null || disposed) return;
            if (reduced) {
                draw(performance.now());
                return;
            }
            last = 0;
            raf = requestAnimationFrame(tick);
        };
        const stop = () => {
            if (raf !== null) cancelAnimationFrame(raf);
            raf = null;
        };

        startRevealRef.current = () => {
            if (!reduced && revealStart < 0) {
                revealStart = performance.now();
                t0 = revealStart;
            }
        };

        let ro: ResizeObserver | null = null;
        let io: IntersectionObserver | null = null;

        import('../../data/thinker-ascii').then((m) => {
            if (disposed) return;
            art = {
                cols: m.THINKER_COLS,
                rows: m.THINKER_ROWS,
                cell: m.THINKER_CELL,
                floorRow: m.THINKER_FLOOR_ROW,
                inkCol: m.THINKER_INK_COL,
                screen: m.THINKER_SCREEN,
                word: m.THINKER_WORD,
                colours: m.THINKER_COLOURS,
                glyphs: m.THINKER_GLYPHS,
                colourRows: m.THINKER_COLOUR_ROWS,
                alphaRows: m.THINKER_ALPHA_ROWS,
                backingRows: m.THINKER_BACKING_ROWS,
            };
            prepare(art);
            layout();
            if (revealedRef.current) startRevealRef.current?.();
            draw(performance.now());
            ro = new ResizeObserver(() => {
                layout();
                draw(performance.now());
            });
            ro.observe(canvas.parentElement ?? canvas);
            io = new IntersectionObserver(([e]) => (e.isIntersecting ? start() : stop()));
            io.observe(canvas);
        });

        return () => {
            disposed = true;
            stop();
            ro?.disconnect();
            io?.disconnect();
            startRevealRef.current = null;
        };
    }, []);

    // The wrapper takes the position (a canvas set with both left and right would keep
    // its intrinsic width); the canvas is sized in layout(), a little wider than the
    // wrapper when the halo spills to the left.
    return (
        <div className={`pointer-events-none ${className}`} style={style}>
            <canvas
                ref={canvasRef}
                aria-label="Rodin's Thinker drawn in text, looking at a laptop"
                role="img"
                className="absolute top-0 block"
            />
        </div>
    );
}
